In joint_3d_gizmo_plugin.cpp:
node_body_a and node_body_b are dereferenced without checking whether Object::cast_to<Node3D> actually succeeded:
Node3D *node_body_a = nullptr;
if (!joint->get_node_a().is_empty()) {
node_body_a = Object::cast_to<Node3D>(joint->get_node(joint->get_node_a()));
Vector3 pos = node_body_a->get_global_position(); // Segfault if node_body_a is null
If the NodePath is invalid (e.g. points to a deleted node, an invalid path, or a node that doesn't inherit from Node3D), get_node() or cast_to will return nullptr. Calling get_global_position() on it will immediately crash the editor.
Wrapping the position lookup and redraw check inside an "if (node_body_a)" check (and similarly for node_body_b) should resolve this:
if (!joint->get_node_a().is_empty()) {
node_body_a = Object::cast_to<Node3D>(joint->get_node(joint->get_node_a()));
if (node_body_a) {
Vector3 pos = node_body_a->get_global_position();
Vector3 &prev_pos = it->value.node_a_last_global_pos;
code
Code
if (!pos.is_equal_approx(prev_pos)) {
        prev_pos = pos;
        perform_redraw = true;
    }
}
}
